castle-gate.source:
const H = params.height;
const S = H / 8;
const towerR = 1.45 * S;
const towerH = 6.9 * S;
const towerX = 3.05 * S;
const wallD = 1.9 * S;
const gateHalf = 1.15 * S;
const springY = 2.7 * S;
const archR = gateHalf;
const crownY = springY + archR;
const stone = { preset: 'stone', color: params.stoneColor, roughness: 0.92, flatShading: true };
const darkStone = { preset: 'stone', color: api.mix(params.stoneColor, '#282826', 0.32), roughness: 0.95, flatShading: true };
const iron = { preset: 'metal', color: '#25282a', metalness: 0.72, roughness: 0.42 };
const wood = { preset: 'wood', color: '#4b3120', roughness: 0.88 };
const addStone = (mesh) => {
  mesh.vertexColor((x, y, z) => api.mix(params.stoneColor, '#5d594f', 0.10 + 0.10 * (api.noise3(x * 1.7, y * 1.7, z * 1.7) + 1) * 0.5));
  api.add(mesh, stone);
};
addStone(api.cylinder(towerR * 0.96, towerR, towerH, 16).translate(-towerX, towerH / 2, 0));
addStone(api.cylinder(towerR * 0.96, towerR, towerH, 16).translate(towerX, towerH / 2, 0));
addStone(api.box(towerX * 2, springY, wallD).translate(0, springY / 2, 0));
addStone(api.box(towerX * 2, 1.7 * S, wallD).translate(0, crownY + 0.85 * S, 0));
addStone(api.box(towerX - gateHalf, crownY - springY, wallD).translate(-(towerX + gateHalf) / 2, (springY + crownY) / 2, 0));
addStone(api.box(towerX - gateHalf, crownY - springY, wallD).translate((towerX + gateHalf) / 2, (springY + crownY) / 2, 0));
const archOuter = archR + 0.38 * S;
const archSegs = 11;
for (let side = -1; side <= 1; side += 2) {
  const z = side * (wallD / 2 + 0.035 * S);
  for (let i = 0; i < archSegs; i++) {
    const a0 = i * Math.PI / archSegs;
    const a1 = (i + 1) * Math.PI / archSegs;
    const shape = [
      [Math.cos(a0) * archR, springY + Math.sin(a0) * archR],
      [Math.cos(a0) * archOuter, springY + Math.sin(a0) * archOuter],
      [Math.cos(a1) * archOuter, springY + Math.sin(a1) * archOuter],
      [Math.cos(a1) * archR, springY + Math.sin(a1) * archR]
    ];
    const voussoir = api.extrude(shape, 0.15 * S).translate(0, 0, z);
    voussoir.vertexColor(() => i % 2 === 0 ? api.mix(params.stoneColor, '#d3c9ae', 0.18) : api.mix(params.stoneColor, '#504c45', 0.12));
    api.add(voussoir, stone);
  }
}
for (let side = -1; side <= 1; side += 2) {
  addStone(api.box(0.34 * S, springY, 0.16 * S).translate(side * (gateHalf + 0.19 * S), springY / 2, wallD / 2 + 0.04 * S));
  addStone(api.box(0.34 * S, springY, 0.16 * S).translate(side * (gateHalf + 0.19 * S), springY / 2, -wallD / 2 - 0.04 * S));
}
const gateZ = wallD / 2 + 0.14 * S;
for (let i = -3; i <= 3; i++) {
  const x = i * gateHalf * 0.285;
  const top = springY + Math.sqrt(Math.max(0, archR * archR - x * x)) - 0.13 * S;
  const bottom = 0.28 * S;
  api.add(api.box(0.075 * S, top - bottom, 0.09 * S).translate(x, (top + bottom) / 2, gateZ), iron);
  api.add(api.cone(0.095 * S, 0.32 * S, 6).rotate(180, 0, 0).translate(x, bottom, gateZ), iron);
}
for (let j = 0; j < 3; j++) {
  api.add(api.box(gateHalf * 1.9, 0.085 * S, 0.11 * S).translate(0, (0.9 + j * 0.72) * S, gateZ + 0.01 * S), iron);
}
const walkY = 5.82 * S;
addStone(api.box(towerX * 2.1, 0.25 * S, wallD * 1.25).translate(0, walkY, 0));
for (let side = -1; side <= 1; side += 2) {
  const z = side * wallD * 0.69;
  addStone(api.box(towerX * 2.15, 0.34 * S, 0.24 * S).translate(0, walkY + 0.29 * S, z));
  for (let i = -4; i <= 4; i++) {
    addStone(api.box(0.45 * S, 0.58 * S, 0.34 * S).translate(i * 0.72 * S, walkY + 0.72 * S, z));
  }
}
for (let t = -1; t <= 1; t += 2) {
  addStone(api.cylinder(towerR * 1.08, towerR * 1.08, 0.25 * S, 16).translate(t * towerX, towerH + 0.02 * S, 0));
  for (let i = 0; i < 12; i++) {
    const a = i * Math.PI * 2 / 12;
    const rr = towerR * 0.96;
    addStone(api.box(0.48 * S, 0.62 * S, 0.48 * S).rotate(0, -a * 180 / Math.PI, 0).translate(t * towerX + Math.cos(a) * rr, towerH + 0.43 * S, Math.sin(a) * rr));
  }
}
for (let t = -1; t <= 1; t += 2) {
  for (let side = -1; side <= 1; side += 2) {
    api.add(api.box(0.16 * S, 0.72 * S, 0.06 * S).translate(t * towerX, 3.55 * S, side * (towerR + 0.015 * S)), darkStone);
    api.add(api.box(0.42 * S, 0.12 * S, 0.065 * S).translate(t * towerX, 3.55 * S, side * (towerR + 0.025 * S)), darkStone);
  }
}
const rearZ = -wallD / 2 - 0.09 * S;
for (let side = -1; side <= 1; side += 2) {
  api.add(api.box(0.48 * S, 1.05 * S, 0.11 * S).translate(side * 1.72 * S, 1.05 * S, rearZ), wood);
  api.add(api.box(0.07 * S, 1.08 * S, 0.13 * S).translate(side * 1.72 * S, 1.05 * S, rearZ - 0.02 * S), iron);
}
api.add(api.box(0.72 * S, 0.42 * S, 0.09 * S).translate(0, 5.12 * S, wallD / 2 + 0.07 * S), darkStone);
api.collider({ kind: 'cylinder', radius: towerR, halfHeight: towerH / 2, offset: [-towerX, towerH / 2, 0] });
api.collider({ kind: 'cylinder', radius: towerR, halfHeight: towerH / 2, offset: [towerX, towerH / 2, 0] });
api.collider({ kind: 'box', halfExtents: [(towerX - gateHalf) / 2, springY / 2, wallD / 2], offset: [-(towerX + gateHalf) / 2, springY / 2, 0] });
api.collider({ kind: 'box', halfExtents: [(towerX - gateHalf) / 2, springY / 2, wallD / 2], offset: [(towerX + gateHalf) / 2, springY / 2, 0] });
api.collider({ kind: 'box', halfExtents: [towerX, 0.85 * S, wallD / 2], offset: [0, crownY + 0.85 * S, 0] });
return api.build();

fountain.source:
const R = params.radius;
const stone = { preset: 'stone', roughness: 0.9, flatShading: true };
const basin = api.lathe([[0, 0], [R, 0], [R, R * 0.25], [R * 0.9, R * 0.25], [R * 0.9, R * 0.08], [0, R * 0.08]], 24);
basin.vertexColor((x, y, z) => api.mix(params.stoneColor, '#6f6a62', 0.25 + 0.25 * api.noise3(x * 2, y * 2, z * 2)));
api.add(basin, stone);
const water = { preset: 'water', color: params.waterColor, opacity: 0.8, roughness: 0.05, emissive: params.waterColor, emissiveIntensity: 0.15 };
api.add(api.cylinder(R * 0.9, R * 0.9, 0.04, 24).translate(0, R * 0.2, 0), water);
const pillar = api.lathe([[0, 0], [R * 0.16, 0], [R * 0.11, R * 0.4], [R * 0.13, R * 0.75], [0, R * 0.75]], 12);
pillar.vertexColor(() => params.stoneColor);
api.add(pillar, stone);
const bowl = api.lathe([[0, R * 0.7], [R * 0.45, R * 0.75], [R * 0.5, R * 0.9], [R * 0.44, R * 0.9], [R * 0.4, R * 0.8], [0, R * 0.8]], 18);
bowl.vertexColor(() => params.stoneColor);
api.add(bowl, stone);
api.add(api.cylinder(R * 0.4, R * 0.4, 0.03, 18).translate(0, R * 0.86, 0), water);
const jet = api.cone(R * 0.06, R * 0.45, 8).translate(0, R * 1.08, 0);
api.add(jet, { preset: 'water', color: '#cfefff', emissive: '#9fdcff', emissiveIntensity: 0.8, opacity: 0.7 });
api.collider({ kind: 'cylinder', radius: R, halfHeight: R * 0.125, offset: [0, R * 0.125, 0] });
api.collider({ kind: 'cylinder', radius: R * 0.16, halfHeight: R * 0.45, offset: [0, R * 0.45, 0] });
return api.build();

hero-fountain.source:
const s = params.width / 3.4;
const stoneMat = { preset: 'stone', roughness: 0.92, flatShading: true };
const waterMat = { preset: 'water', color: params.waterColor, opacity: 0.7, roughness: 0.05, emissive: params.waterColor, emissiveIntensity: 0.5 };
const sheetMat = { preset: 'water', color: '#bfe6ff', opacity: 0.45, roughness: 0.05, emissive: '#7fc8ff', emissiveIntensity: 0.8 };
function stone(m, dark) {
  m.vertexColor((x, y, z) => {
    const n = api.noise3(x * 3, y * 3, z * 3);
    let c = api.mix(params.stoneColor, '#8a6c4a', 0.2 + 0.2 * n + (dark || 0));
    if (y < 0.3) c = api.mix(c, '#5f6b45', 0.2);
    return c;
  });
  api.add(m.scale(s), stoneMat);
}
function water(m) { api.add(m.scale(s), waterMat); }
function sheet(m) { api.add(m.scale(s), sheetMat); }
// basin
stone(api.lathe([[0,0],[1.45,0],[1.55,0.08],[1.6,0.15],[1.6,0.68],[1.68,0.7],[1.72,0.76],[1.72,0.82],[1.55,0.82],[1.5,0.74],[1.45,0.7],[1.45,0.28],[0,0.28]], 8));
stone(api.cylinder(1.5, 1.55, 0.06, 8).translate(0, 0.03, 0), 0.1);
water(api.cylinder(1.43, 1.43, 0.03, 8).translate(0, 0.62, 0));
if (params.panels) {
  const ap = 1.6 * Math.cos(Math.PI / 8);
  for (let k = 0; k < 8; k++) {
    const a = 22.5 + 45 * k, r = a * Math.PI / 180;
    const px = Math.sin(r) * (ap + 0.015), pz = Math.cos(r) * (ap + 0.015);
    stone(api.box(0.8, 0.38, 0.05).rotate(0, a, 0).translate(px, 0.4, pz), -0.1);
    stone(api.box(0.6, 0.22, 0.06).rotate(0, a, 0).translate(Math.sin(r) * (ap + 0.03), 0.4, Math.cos(r) * (ap + 0.03)), 0.12);
  }
}
// pedestal
stone(api.lathe([[0,0.28],[0.5,0.28],[0.5,0.36],[0.36,0.45],[0.3,0.6],[0.24,0.7],[0.24,1.1],[0.3,1.2],[0.34,1.3],[0,1.3]], 16));
stone(api.cylinder(0.22, 0.22, 0.5, 16).translate(0, 0.9, 0));
for (let i = 0; i < 12; i++) {
  const a = i / 12 * Math.PI * 2;
  stone(api.cylinder(0.03, 0.03, 0.5, 6).translate(Math.sin(a) * 0.235, 0.9, Math.cos(a) * 0.235), 0.12);
}
// bowl 1 scalloped
const b1 = api.lathe([[0,1.25],[0.2,1.25],[0.3,1.35],[0.95,1.6],[1.0,1.66],[1.0,1.72],[0.92,1.72],[0.85,1.6],[0.2,1.45],[0,1.45]], 24);
b1.displace((x, y, z) => y > 1.4 ? 0.03 * Math.cos(Math.atan2(x, z) * 12) : 0);
stone(b1);
water(api.cylinder(0.85, 0.85, 0.03, 24).translate(0, 1.62, 0));
stone(api.cylinder(0.14, 0.16, 0.6, 12).translate(0, 1.75, 0));
// bowl 2
const b2 = api.lathe([[0,1.95],[0.12,1.95],[0.2,2.02],[0.57,2.2],[0.62,2.25],[0.62,2.3],[0.55,2.3],[0.5,2.2],[0.12,2.1],[0,2.1]], 20);
b2.displace((x, y, z) => y > 2.1 ? 0.025 * Math.cos(Math.atan2(x, z) * 10) : 0);
stone(b2);
water(api.cylinder(0.48, 0.48, 0.03, 20).translate(0, 2.2, 0));
// finial
stone(api.cylinder(0.06, 0.09, 0.5, 10).translate(0, 2.35, 0));
stone(api.cylinder(0.12, 0.1, 0.05, 10).translate(0, 2.58, 0));
const pc = api.sphere(0.17, 2).scale(1, 1.4, 1).translate(0, 2.8, 0);
pc.displace((x, y, z) => 0.025 * Math.sin(y * 40 + Math.atan2(x, z) * 6));
stone(pc, 0.05);
stone(api.cone(0.05, 0.12, 8).translate(0, 3.0, 0));
// falling sheets
for (let i = 0; i < 8; i++) {
  const a = i * 45 + 22.5, r = a * Math.PI / 180;
  sheet(api.box(0.1, 0.4, 0.012).rotate(0, a, 0).translate(Math.sin(r) * 0.63, 1.95, Math.cos(r) * 0.63));
  sheet(api.box(0.12, 1.0, 0.012).rotate(0, a, 0).translate(Math.sin(r) * 1.0, 1.12, Math.cos(r) * 1.0));
}
sheet(api.cylinder(0.025, 0.025, 0.2, 6).translate(0, 3.05, 0));
// colliders
api.collider({ kind: 'cylinder', radius: 1.7 * s, halfHeight: 0.41 * s, offset: [0, 0.41 * s, 0] });
api.collider({ kind: 'cylinder', radius: 0.3 * s, halfHeight: 0.8 * s, offset: [0, 1.0 * s, 0] });
api.collider({ kind: 'cylinder', radius: 1.0 * s, halfHeight: 0.25 * s, offset: [0, 1.5 * s, 0] });
api.collider({ kind: 'cylinder', radius: 0.6 * s, halfHeight: 0.2 * s, offset: [0, 2.15 * s, 0] });
api.collider({ kind: 'cylinder', radius: 0.1 * s, halfHeight: 0.4 * s, offset: [0, 2.6 * s, 0] });
return api.build();

beach-umbrella.source:
const main = params.color;
const stripe = params.stripeColor;
const tilt = params.tilt;
const ang = tilt * Math.PI / 180;
const cs = Math.cos(ang);
const sn = Math.sin(ang);
const poleH = 2.35;
const poleR = 0.027;
const canopyR = 1.18;
const hubY = 2.16;
const tx = -sn * poleH * 0.5;
const ty = cs * poleH * 0.5;
const point = (x, y, z) => [x * cs - y * sn, x * sn + y * cs, z];
const fabric = { preset: 'fabric', roughness: 0.82, flatShading: true };
const wood = { preset: 'wood', color: '#9a673d', roughness: 0.62 };
const metal = { preset: 'metal', color: '#d8d2c3', metalness: 0.65, roughness: 0.32 };
const sand = { preset: 'sand', color: '#d9bd83', roughness: 1, flatShading: true };
api.add(api.icosphereRock(0.34, 0.32).scale(1.55, 0.28, 1.35).translate(0, 0.06, 0), sand);
api.add(api.cylinder(poleR, poleR * 1.08, poleH, 12).rotate(0, 0, tilt).translate(tx, ty, 0), wood);
const capProfile = [[0, hubY + 0.34], [canopyR * 0.2, hubY + 0.3], [canopyR * 0.48, hubY + 0.19], [canopyR * 0.76, hubY + 0.03], [canopyR, hubY - 0.16], [canopyR * 0.98, hubY - 0.22], [canopyR * 0.74, hubY - 0.04], [canopyR * 0.47, hubY + 0.12], [canopyR * 0.19, hubY + 0.24], [0, hubY + 0.28]];
const canopy = api.lathe(capProfile, 32).rotate(0, 0, tilt);
canopy.vertexColor((x, y, z) => {
  let a = Math.atan2(z, x);
  if (a < 0) a += Math.PI * 2;
  return Math.floor(a / (Math.PI / 4)) % 2 === 0 ? main : stripe;
});
api.add(canopy, fabric);
const top = point(0, hubY + 0.35, 0);
api.add(api.sphere(0.065, 1).translate(top[0], top[1], top[2]), metal);
const hub = point(0, hubY - 0.03, 0);
api.add(api.cylinder(0.065, 0.075, 0.12, 12).rotate(0, 0, tilt).translate(hub[0], hub[1], hub[2]), metal);
for (let i = 0; i < 8; i++) {
  const a = i * Math.PI / 4;
  const inner = point(Math.cos(a) * 0.07, hubY - 0.02, Math.sin(a) * 0.07);
  const edge = point(Math.cos(a) * canopyR * 0.94, hubY - 0.17, Math.sin(a) * canopyR * 0.94);
  api.add(api.tube([inner, edge], 0.012, 6), metal);
  const braceStart = point(Math.cos(a) * 0.03, hubY - 0.23, Math.sin(a) * 0.03);
  const braceEnd = point(Math.cos(a) * canopyR * 0.48, hubY + 0.06, Math.sin(a) * canopyR * 0.48);
  api.add(api.tube([braceStart, braceEnd], 0.009, 6), metal);
}
const towelW = 0.82;
const towelL = 1.48;
const towel = api.box(towelW, 0.018, towelL).translate(0.62, 0.105, 0.28);
towel.vertexColor((x, y, z) => Math.floor((z + towelL * 0.5) / (towelL / 7)) % 2 === 0 ? main : stripe);
api.add(towel, fabric);
for (let side = -1; side <= 1; side += 2) {
  for (let j = 0; j < 9; j++) {
    const x = 0.62 - towelW * 0.44 + j * towelW * 0.11;
    const z = 0.28 + side * (towelL * 0.5 + 0.045);
    api.add(api.cylinder(0.007, 0.007, 0.09, 5).rotate(90, 0, 0).translate(x, 0.105, z), { preset: 'fabric', color: stripe, roughness: 0.9 });
  }
}
api.collider({ kind: 'box', halfExtents: [0.045, poleH * 0.5, 0.045], offset: [tx, ty, 0], rotation: [0, 0, tilt] });
api.collider({ kind: 'box', halfExtents: [canopyR * 0.72, 0.18, canopyR * 0.72], offset: point(0, hubY + 0.08, 0), rotation: [0, 0, tilt] });
api.collider({ kind: 'box', halfExtents: [towelW * 0.5, 0.012, towelL * 0.5], offset: [0.62, 0.105, 0.28] });
return api.build();

lisbon-houses2.source:
const sm=(a,b,x)=>{const t=Math.min(1,Math.max(0,(x-a)/(b-a)));return t*t*(3-2*t);};
const hs=(i,j)=>{const n=Math.sin(i*127.1+j*311.7)*43758.5453;return n-Math.floor(n);};
